"""Original multivariable replacements following independent shortest-route review."""
from common import *
reg=Registry('multivariable');register=reg.register
x,y,t=s.symbols('x y t',real=True)

@register('Hessian-from-boundary-data','Hessian-determinant-null-Lagrangian','Show that a nonlinear interior Hessian integral is determined entirely by prescribed boundary normal data, although the interior function is unspecified.','The explicit-polynomial predecessor allowed direct differentiation; arbitrary smooth interior freedom makes the boundary null-Lagrangian identity indispensable.',[{'n':n} for n in range(1,11)],'cofactor-divergence-and-boundary-curvature',('Hessian matrices','divergence theorem','boundary differentiation'))
def hessian_boundary(n):
 a=R(1,2);b=1/(n+1);g=1+a*s.cos(n*t)+b*s.sin((n+1)*t);answer=s.pi*(1+(a*a+b*b)/2)
 u=s.Function('u')(x,y);H=s.hessian(u,(x,y));F=H.adjugate()*s.Matrix([s.diff(u,x),s.diff(u,y)]);rho=s.symbols('rho',positive=True);w=(rho*rho-1)*(1+a*rho**n*s.cos(n*t)+b*rho**(n+1)*s.sin((n+1)*t))/2
 pool=[(2*answer,'omit the factor two in the cofactor divergence'),(answer/2,'apply the divergence normalization twice'),(s.pi*(1+a*a+b*b),'replace each nonconstant squared trigonometric mean by one'),(s.pi*(1+(a*a-b*b)/2),'give the sine-square contribution a negative sign'),(s.pi*(1+(a+b)**2/2),'keep an orthogonal cross-frequency term'),(s.pi*(1+(a-b)**2/2),'subtract a nonexistent cross-frequency term'),(s.pi*(a*a+b*b)/2,'omit the constant normal-derivative mode')]
 Q=T('Let u be any real function with three continuous derivatives on a neighborhood of the closed unit disk D. Its boundary value and outward unit-normal derivative are prescribed below. Determine the integral, which has the same value for every such u.')+r'\quad D=\{(x,y):x^2+y^2\le1\},\quad u|_{\partial D}=0,\quad u_n(\cos\theta,\sin\theta)=1+\frac12\cos('+L(n)+r'\theta)+'+L(b)+r'\sin('+L(n+1)+r'\theta),\qquad\iint_D(u_{xx}u_{yy}-u_{xy}^2)\,\mathrm dx\,\mathrm dy=?'
 steps=[T('Write H for the Hessian and cof H for its cofactor matrix. Commuting third derivatives gives the divergence identity ')+r'\nabla\cdot\bigl((\operatorname{cof}H)\nabla u\bigr)=2\det H.',T('On the boundary the tangential derivative vanishes, so the gradient equals its normal component times the outward unit normal. Twice differentiating the zero boundary trace along the unit circle gives ')+r'\tau^{\mathsf T}H\tau=u_n,\qquad n^{\mathsf T}(\operatorname{cof}H)\nabla u=u_n^2.',T('The divergence theorem therefore removes all unspecified interior values.'),r'\iint_D\det H\,\mathrm dx\,\mathrm dy=\frac12\int_0^{2\pi}u_n(\cos\theta,\sin\theta)^2\,\mathrm d\theta.',T('The constant Fourier mode contributes two pi, each squared nonconstant mode contributes pi, and all mixed integrals vanish.'),r'\frac12\int_0^{2\pi}u_n^2\,\mathrm d\theta=\pi\left[1+\frac12\left(\frac14+'+L(b*b)+r'\right)\right].',T('The prescribed class is nonempty: in polar coordinates the following expression is a smooth polynomial in the Cartesian coordinates and has exactly the required boundary data.'),r'u_0(r,\theta)=\frac{r^2-1}{2}\left(1+\frac12r^{'+L(n)+r'}\cos('+L(n)+r'\theta)+'+L(b)+r'r^{'+L(n+1)+r'}\sin('+L(n+1)+r'\theta)\right).']
 checks=[check('generic cofactor divergence',s.diff(F[0],x)+s.diff(F[1],y),2*H.det()),check('independent Fourier boundary integral',s.integrate(s.expand_trig(g*g),(t,0,2*s.pi))/2,answer),check('existence witness zero trace',w.subs(rho,1)),check('existence witness normal derivative',s.diff(w,rho).subs(rho,1),g)]
 return item(Q,answer,pool,steps,checks,['The boundary normal n is outward and has unit length; subscripts x,y denote ordinary partial derivatives. D has unit radius.'],['C3 regularity ensures the divergence identity and classical divergence theorem. The unit-circle parametrization has second derivative minus its outward normal, so the second derivative of the zero trace gives tau^T H tau=u_n with the displayed positive sign. In two dimensions n^T cof(H)n=tau^T H tau. Orthogonality of distinct integer sine/cosine modes evaluates the boundary norm. The witness is polynomial because r^k cos(k theta) and r^k sin(k theta) are real/imaginary parts of (x+iy)^k; it proves the requested data are feasible.'],'arbitrary-interior-Hessian-integral-fixed-by-boundary-normal-data')

@register('disk-Fekete-maximum','disk-Fekete-Hadamard-extremality','Turn the full pairwise distance product into a Vandermonde determinant, obtain a dimension-wide norm bound, and realize equality with a configuration of points.','Different from the integrated Gram determinant: this is a global nonlinear optimization with a sharp matrix-norm equality case, without stationary equations for all point coordinates.',[{'n':n} for n in range(5,15)],'Vandermonde-Hadamard-and-roots-of-unity',('complex numbers','determinants','Cauchy-Schwarz or Hadamard inequality'))
def fekete(n):
 answer=n**n;N=n*(n-1)/2
 pool=[(n**(n-1),'drop one row-norm contribution'),(n**(n+1),'count an extra row norm'),(s.factorial(n)**2,'replace orthogonal row norms by a permutation count'),((n-1)**n,'omit the constant Vandermonde column'),((n+1)**n,'include an extra Vandermonde column'),(2**(n*(n-1)),'assume every pair can be antipodal simultaneously'),(n**(2*n),'forget the square root in Hadamard before squaring')]
 Q=T('Choose arbitrary complex points in the closed unit disk. Repetitions are allowed. Find the greatest possible value of the displayed pairwise distance product.')+r'\quad z_1,\ldots,z_{'+L(n)+r'}\in\mathbb C,\quad |z_j|\le1,\qquad\max\prod_{1\le i<j\le'+L(n)+r'}|z_i-z_j|^2=?'
 steps=[T('Put the powers of each point in a row of the Vandermonde matrix. Its determinant is the product of pairwise differences.'),r'V_{jk}=z_j^{k-1}\quad(1\le j,k\le'+L(n)+r'),\qquad|\det V|^2=\prod_{i<j}|z_i-z_j|^2.',T('Each row has squared Euclidean norm at most the number of columns. Hadamard inequality bounds a determinant by the product of row norms.'),r'\sum_{k=0}^{'+L(n-1)+r'}|z_j|^{2k}\le'+L(n)+r',\qquad|\det V|^2\le'+L(n)+r'^{'+L(n)+r'}.',T('Take all distinct roots of unity of this order. Every row then has the maximal norm, and distinct rows are orthogonal because their inner product is a geometric sum with nontrivial unit ratio.'),r'z_j=e^{2\pi i(j-1)/'+L(n)+r'},\qquad\sum_{k=0}^{'+L(n-1)+r'}(z_j\overline{z_\ell})^k=0\quad(j\ne\ell).',T('Thus equality in Hadamard is attained, proving that the upper bound is the requested maximum. Here i is the imaginary unit and the bar denotes complex conjugation.')]
 # At roots of unity, the Vandermonde square modulus equals the discriminant
 # modulus of X^n-1. This is an independent exact polynomial computation.
 P=x**n-1;disc=s.discriminant(P,x)
 checks=[check('independent roots-of-unity discriminant modulus',abs(disc),answer),check('finite geometric numerator polynomial identity',(x-1)*sum(x**j for j in range(int(n))),x**n-1),truth('nontrivial configuration size',bool(n>=5))]
 return item(Q,answer,pool,steps,checks,['Absolute value denotes complex modulus. The disk is closed and has radius one. The repeated-point case has product zero and is included.'],['The Vandermonde determinant identity is a polynomial identity. Hadamard follows by orthogonalizing its rows and applying the fact that orthogonal projections cannot increase lengths. The row norm bound uses |z|<=1 term by term. Distinct nth roots give a geometric ratio different from one whose nth power is one, so each off-diagonal row inner product is zero. Equality is therefore achieved by a feasible configuration. The exact discriminant of X^n-1 separately verifies the resulting pair product.'],'global-unit-disk-distance-product-Hadamard-equality')

@register('disk-to-annulus-optimal-transport','radial-quantile-quadratic-transport','Prove the globally optimal coupling by angular alignment and a sharp scalar rearrangement bound, then evaluate the radial quantile cost.','Unlike an ordinary change of variables, the map is unknown and must be proved optimal over every coupling, including randomized ones.',[{'a':str(R(1,k))} for k in range(2,12)],'radial-quantile-coupling-and-rearrangement',('probability densities','polar coordinates','layer-cake integral'))
def transport(a):
 b=s.sqrt(1+a*a);r=s.symbols('r',positive=True);J=b*(a*a+2)/8-a**4*s.asinh(1/a)/8;answer=1+a*a-4*J
 pool=[(1+a*a-b*(a*a+2)/2-a**4*s.asinh(1/a)/2,'reverse the inverse-hyperbolic primitive sign'),(1+a*a-b*(a*a+2)/4+a**4*s.asinh(1/a)/4,'halve the cross-moment contribution'),(1+a*a-2*(b**3-a**3)/3,'use uniform radius instead of uniform area'),(1+a*a-b*(a*a+2)/2+a*a*s.asinh(1/a)/2,'omit two powers of the inner radius in the primitive'),(R(1,2)+(1+2*a*a)/(2*(1+a*a))-4*J,'normalize the target by the outer disk area instead of annulus area'),(1+a*a-b*(a*a+2)/2+a**4*s.asinh(1/a),'double the inverse-hyperbolic endpoint contribution')]
 Q=T('Let X be uniformly distributed on the closed unit disk in the real plane, and let Y be uniformly distributed on the annulus below. Among all joint distributions with these two marginals, find the smallest expected squared Euclidean distance.')+r'\quad '+L(a*a)+r'\le |Y|^2\le'+L(1+a*a)+r',\qquad\inf\mathbb E\bigl[|X-Y|^2\bigr]=?'+T('Here uniform means normalized planar area; dependence between X and Y may be chosen freely. The inverse hyperbolic sine has its real convention ')+r'\operatorname{arcsinh}v=\ln(v+\sqrt{1+v^2}).'
 steps=[T('Write R and S for the radii of X and Y. Their squared radii have uniform distributions on the respective area-coordinate intervals.'),r'R^2\sim\operatorname{Unif}[0,1],\qquad S^2\sim\operatorname{Unif}['+L(a*a)+','+L(1+a*a)+r'],\qquad\mathbb E|X-Y|^2=1+'+L(a*a)+r'-2\mathbb E(X\cdot Y).',T('Pointwise angular alignment gives X dot Y at most R times S. To maximize the product expectation of two nonnegative bounded variables, write it as the double integral of their joint survival probability. Each joint survival probability is at most the smaller marginal survival probability.'),r'\mathbb E(RS)=\int_0^\infty\!\int_0^\infty\mathbb P(R>u,S>v)\,\mathrm du\,\mathrm dv,\qquad\mathbb P(R>u,S>v)\le\min\{\mathbb P(R>u),\mathbb P(S>v)\}.',T('All these bounds are attained simultaneously by using the same uniform variable for both squared radii and the same independent uniform angle. This proves global optimality over all joint distributions.'),r'R=\sqrt U,\quad S=\sqrt{'+L(a*a)+r'+U},\quad U\sim\operatorname{Unif}[0,1],\qquad\max\mathbb E(X\cdot Y)=2\int_0^1r^2\sqrt{'+L(a*a)+r'+r^2}\,\mathrm dr.',T('Let a denote the positive inner radius in this problem. A chosen primitive for the final one-variable integral is ')+r'a='+L(a)+r',\qquad F(r)=\frac{r\sqrt{a^2+r^2}(a^2+2r^2)-a^4\operatorname{arcsinh}(r/a)}8.',r'\int_0^1r^2\sqrt{a^2+r^2}\,\mathrm dr=F(1)-F(0)=\frac{\sqrt{1+a^2}(a^2+2)-a^4\operatorname{arcsinh}(1/a)}8.',T('Substitute this cross moment into the squared-distance identity.')]
 F=(r*s.sqrt(a*a+r*r)*(a*a+2*r*r)-a**4*s.asinh(r/a))/8
 checks=[check('independent primitive derivative',s.diff(F,r),r*r*s.sqrt(a*a+r*r)),check('primitive endpoint value',F.subs(r,1)-s.limit(F,r,0),J),check('source second radial moment',s.integrate(2*r**3,(r,0,1)),R(1,2)),check('target second radial moment',s.integrate(r,(r,a*a,1+a*a)),R(1,2)+a*a),truth('nonempty nondegenerate annulus',bool(a>0))]
 return item(Q,answer,pool,steps,checks,['Both marginal measures have total mass one. Infimum is over all probability measures on pairs with these marginals, not only deterministic transport maps. The displayed coupling attains it.'],['Uniform planar area gives squared radius uniform on the squared radial interval and independent uniform angle. Dot-product comparison is pointwise. Nonnegative layer-cake integration follows from Tonelli, and the intersection of two upper-tail intervals in a common uniform variable has probability equal to the smaller tail probability, establishing sharpness of the rearrangement bound. Equal angles attain the angular bound at the same time. Bounded supports ensure every expectation is finite. The cost integral is checked by an independently differentiated primitive with positive arguments throughout.'],'uniform-disk-annulus-Wasserstein-radial-quantile-optimum')

catalog=reg.catalog;build=reg.build;verify=reg.verify;all_candidates=reg.all_candidates
if __name__=='__main__':
 import json,hashlib
 from pathlib import Path
 root=Path(__file__).resolve().parent;rows=list(all_candidates());tmp=root/'mv-additions.jsonl.tmp';tmp.write_text(''.join(json.dumps(r,sort_keys=True,default=str)+'\n' for r in rows));tmp.replace(root/'mv-additions.jsonl');(root/'mv-additions-verification.json').write_text(json.dumps({'records':len(rows),'executedChecks':sum(len(r['verificationEvidence']) for r in rows),'sourceSha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),'status':'candidate-awaiting-independent-review'},indent=2)+'\n');print(len(rows),'records')
